/// <summary>
/// MPJ_28153 Interbranch Transfers	DCP 01/08/2022
/// </summary>
[ExtensionOf(tableStr(InventTransferLine))]
final class METInventTransferLineTable_Extension
{
}

Method.Source:
    /// <summary>
    /// Reduce the Ship Remain qty to match what was pickied
    /// </summary>
    /// <param name = "_pickingRouteId">Picking route id</param>
    public static void METAdjustShipRemain(WMSPickingRouteID _pickingRouteId)
    {
        WMSOrderTrans               metWMSOrderTrans;
        InventTransferLine          metInventTransferLine;

        if(!METInventTransferTableExt::isAllowBackorderRouteId(_pickingRouteId))
        {
            while select forupdate metInventTransferLine
                join qty from metWMSOrderTrans
                where   metInventTransferLine.InventTransId == metWMSOrderTrans.inventTransId
                &&      metInventTransferLine.transferId    == metWMSOrderTrans.inventTransRefId
                &&      metWMSOrderTrans.routeId            == _pickingRouteId
                &&      metWMSOrderTrans.inventTransType    == InventTransType::TransferOrderShip
                &&      metWMSOrderTrans.fullPallet         == NoYes::No
            {
                metInventTransferLine.QtyRemainShip = metWMSOrderTrans.qty;

                if (metInventTransferLine.validateWrite())
                {
                    metInventTransferLine.updateDeliverRemainder(); //std code contains ttsbegin and ttscommit
                }
            }
        }
    }
